'use strict';
// Rules pack, mechanics: hard limits, stores, losing a room, destroyed structures, and the three
// seasonal worlds whose rules are public as server mods (seasons 1, 2 and 5).
// Numbers of a season exist only in its mod, so they are typed here with the mod line as source.
const { L, eng, backend, driver, common, ref } = require('../../_h');

const G = 'src/game/';
const P = 'src/processor/intents/';
const GI = 'src/processor/global-intents/';
const RT = 'lib/runtime/';
const SYS = 'lib/system.js';
const API = 'lib/game/api/';
const s1 = (file, find) => ref('mod-season1', 'src/' + file, find);
const s2 = (file, find) => ref('mod-season2', 'src/' + file, find);
const s5 = (file, find) => ref('mod-season5', 'src/' + file, find);
const big = n => (n >= 10000 ? n.toLocaleString('en-US') : String(n));

// "50 (RCL 0-6), 100 (RCL 7), 200 (RCL 8)" from a per-level constant
const byLevel = table => {
    const out = [];
    for (const level of Object.keys(table).map(Number).sort((a, b) => a - b)) {
        const last = out[out.length - 1];
        if (last && last.value === table[level]) last.to = level;
        else out.push({ value: table[level], from: level, to: level });
    }
    return out.map(g => `${big(g.value)} (RCL ${g.from === g.to ? g.from : g.from + '–' + g.to})`).join(', ');
};

